1	import { describe, it, expect } from "vitest";
2	import { nextGeneration, type Cell } from "./game-of-life.js";
3	
4	describe("Game of Life - Next Generation", () => {
5	  it("should return no living cells for a single living cell", () => {
6	    expect(nextGeneration([[0, 0]])).toEqual([]);
7	  });
8	  it("should let both cells die when each has only one live neighbor", () => {
9	    expect(
10	      nextGeneration([
11	        [0, 1],
12	        [1, 1],
13	      ]),
14	    ).toEqual([]);
15	  });
16	  it("should keep a live cell with three live neighbors alive", () => {
17	    expect(
18	      nextGeneration([
19	        [0, 0],
20	        [0, 1],
21	        [0, 2],
22	        [1, 1],
23	      ]),
24	    ).toContainEqual([1, 1]);
25	  });
26	  it("should keep a live cell with two live neighbors alive", () => {
27	    expect(
28	      nextGeneration([
29	        [0, 0],
30	        [0, 1],
31	        [0, 2],
32	      ]),
33	    ).toContainEqual([0, 1]);
34	  });
35	  it("should let a live cell with four live neighbors die", () => {
36	    expect(
37	      nextGeneration([
38	        [0, 0],
39	        [1, 0],
40	        [2, 0],
41	        [1, 1],
42	        [1, 2],
43	      ]),
44	    ).not.toContainEqual([1, 1]);
45	  });
46	  it("should bring a dead cell with exactly three live neighbors to life", () => {
47	    expect(
48	      nextGeneration([
49	        [0, 0],
50	        [0, 1],
51	        [1, 0],
52	      ]),
53	    ).toContainEqual([1, 1]);
54	  });
55	  it("should keep a block unchanged", () => {
56	    const block: Cell[] = [
57	      [0, 0],
58	      [1, 0],
59	      [0, 1],
60	      [1, 1],
61	    ];
62	    const result = nextGeneration(block);
63	    expect(result).toHaveLength(4);
64	    expect(result).toEqual(expect.arrayContaining(block));
65	  });
66	  it("should turn a vertical blinker into a horizontal blinker", () => {
67	    const verticalBlinker: Cell[] = [
68	      [0, 0],
69	      [0, 1],
70	      [0, 2],
71	    ];
72	    const horizontalBlinker: Cell[] = [
73	      [-1, 1],
74	      [0, 1],
75	      [1, 1],
76	    ];
77	    const result = nextGeneration(verticalBlinker);
78	    expect(result).toHaveLength(3);
79	    expect(result).toEqual(expect.arrayContaining(horizontalBlinker));
80	  });
81	  it.todo("should return the blinker to its original state after two generations");
82	  it.todo("should compute the next generation for cells at negative coordinates");
83	});
