1	export type Cell = [number, number];
2	
3	const isSameCell = ([x1, y1]: Cell, [x2, y2]: Cell): boolean =>
4	  x1 === x2 && y1 === y2;
5	
6	const contains = (cells: Cell[], cell: Cell): boolean =>
7	  cells.some((other) => isSameCell(cell, other));
8	
9	const neighborsOf = ([x, y]: Cell): Cell[] => [
10	  [x - 1, y - 1],
11	  [x - 1, y],
12	  [x - 1, y + 1],
13	  [x, y - 1],
14	  [x, y + 1],
15	  [x + 1, y - 1],
16	  [x + 1, y],
17	  [x + 1, y + 1],
18	];
19	
20	const countLiveNeighbors = (cell: Cell, livingCells: Cell[]): number =>
21	  neighborsOf(cell).filter((neighbor) => contains(livingCells, neighbor)).length;
22	
23	const withoutDuplicates = (cells: Cell[]): Cell[] =>
24	  cells.filter(
25	    (cell, index) =>
26	      cells.findIndex((other) => isSameCell(cell, other)) === index,
27	  );
28	
29	const candidates = (livingCells: Cell[]): Cell[] =>
30	  withoutDuplicates([...livingCells, ...livingCells.flatMap(neighborsOf)]);
31	
32	const isAliveNextGeneration = (cell: Cell, livingCells: Cell[]): boolean => {
33	  const liveNeighbors = countLiveNeighbors(cell, livingCells);
34	  const isCurrentlyAlive = contains(livingCells, cell);
35	  return liveNeighbors === 3 || (liveNeighbors === 2 && isCurrentlyAlive);
36	};
37	
38	export const nextGeneration = (livingCells: Cell[]): Cell[] =>
39	  candidates(livingCells).filter((cell) =>
40	    isAliveNextGeneration(cell, livingCells),
41	  );
